def oku(y):
    with open(y, encoding="utf-8") as f:
        return f.read()

def yaz(y, s):
    with open(y, "w", encoding="utf-8") as f:
        f.write(s)

for y in ("app/data/hayrat_tek.tsv", "tools/hayrat_tek_uret.py", "tools/hayrat_tek_supheli.tsv"):
    if not os.path.exists(y):
        print("HATA: bulunamadi:", y, "(osmanlica deposunun kokunde calistirin)")
        sys.exit(1)

# (1) karar dosyasi
KARAR = "tools/hayrat_tek_karar.tsv"
metin = "# Tur M: hayrat_tek_supheli.tsv'deki kelimelerin karari. latince<TAB>karar<TAB>yazim<TAB>hayrat_yazimi\n"
metin += "# H: Hayrat yazimi alinir; D: Hayrat yanlis, dogru yazim; A: alinmaz (cevirici dogru ya da es sesli). hayrat_tek_uret.py bunu okur.\n"
metin += "".join("\t".join(r[:4]) + "\n" for r in VERI)
if os.path.exists(KARAR) and oku(KARAR) == metin:
    print("ATLANDI: karar dosyasi zaten var")
else:
    yaz(KARAR, metin)
    print("TAMAM: karar dosyasi yazildi,", len(VERI), "kelime")

# (2) hayrat_tek.tsv'ye ekleme
satirlar = oku("app/data/hayrat_tek.tsv").split("\n")
mevcut = {s.split("\t")[0] for s in satirlar if s and not s.startswith("#")}
eklenecek = []
for k, c, yz, o, n in VERI:
    if c in ("H", "D") and k not in mevcut:
        eklenecek.append(f"{k}\t{yz}\t{'hayrat' if c == 'H' else 'denetim'}\t{n}")
if not eklenecek:
    print("ATLANDI: hayrat_tek.tsv zaten guncel")
else:
    bas = [s for s in satirlar if s.startswith("#")]
    govde = sorted([s for s in satirlar if s and not s.startswith("#")] + eklenecek)
    yaz("app/data/hayrat_tek.tsv", "\n".join(bas + govde) + "\n")
    print("TAMAM: hayrat_tek.tsv'ye eklendi:", len(eklenecek), "| toplam kayit:", len(govde))

# (3) uretici betik
u = oku("tools/hayrat_tek_uret.py")
if "hayrat_tek_karar.tsv" in u:
    print("ATLANDI: hayrat_tek_uret.py zaten karar dosyasini okuyor")
else:
    eski1 = "cikan = collections.Counter()\nyaz, supheli = [], []\n"
    yeni1 = (eski1 +
        "# Tur M: supheli kelimelerin karari (tools/hayrat_tek_karar.tsv): H Hayrat yazimi, D dogru yazim, A alinmaz\n"
        "KARAR = {}\n"
        "_kd = os.path.join(os.path.dirname(os.path.abspath(__file__)), \"hayrat_tek_karar.tsv\")\n"
        "if os.path.exists(_kd):\n"
        "    for _s in open(_kd, encoding=\"utf-8\"):\n"
        "        _p = _s.rstrip(\"\\n\").split(\"\\t\")\n"
        "        if len(_p) >= 3 and not _s.startswith(\"#\"):\n"
        "            KARAR[_p[0]] = (_p[1], _p[2])\n"
        "KAYNAK = {}\n\n\n"
        "def suphe(k, o, top, simdi, neden):\n"
        "    if k in KARAR:\n"
        "        c, yz = KARAR[k]\n"
        "        if c in (\"H\", \"D\") and yz:\n"
        "            yaz.append((k, yz, top))\n"
        "            KAYNAK[k] = \"hayrat\" if c == \"H\" else \"denetim\"\n"
        "        else:\n"
        "            cikan[\"denetimde alinmadi (Tur M)\"] += 1\n"
        "        return\n"
        "    supheli.append((k, o, top, simdi, neden))\n\n\n")
    if u.count(eski1) != 1:
        print("HATA: hayrat_tek_uret.py'de beklenen metin yok (cikan/yaz satirlari)")
        sys.exit(1)
    u = u.replace(eski1, yeni1)
    n = u.count("        supheli.append((k, o, top, simdi, ")
    if n != 4:
        print("HATA: hayrat_tek_uret.py'de 4 supheli.append bekleniyordu, bulunan:", n)
        sys.exit(1)
    u = u.replace("        supheli.append((k, o, top, simdi, ", "        suphe(k, o, top, simdi, ")
    u = u.replace("\"))\n        continue", "\")\n        continue")
    eski2 = "        f.write(f\"{k}\\t{o}\\thayrat\\t{top}\\n\")"
    if u.count(eski2) != 1:
        print("HATA: hayrat_tek_uret.py'de yazma satiri bulunamadi")
        sys.exit(1)
    u = u.replace(eski2, "        f.write(f\"{k}\\t{o}\\t{KAYNAK.get(k, 'hayrat')}\\t{top}\\n\")")
    yaz("tools/hayrat_tek_uret.py", u)
    print("TAMAM: hayrat_tek_uret.py karar dosyasini okuyor")

# (4) supheli listesi: hepsi karara baglandi
s = oku("tools/hayrat_tek_supheli.tsv").split("\n")
kalan = [x for x in s[1:] if x and x.split("\t")[0] not in {r[0] for r in VERI}]
if len(s) <= 2 and not kalan:
    print("ATLANDI: supheli listesi zaten bos")
else:
    yaz("tools/hayrat_tek_supheli.tsv", s[0] + "\n" + "".join(x + "\n" for x in kalan))
    print("TAMAM: supheli listesinde kalan:", len(kalan))

# (5) dictionary.py: hayrat_tek anahtarinda uzun unlu isareti (a i u makronlu) ve ayrisik harf (NFC)
d = oku("app/engine/dictionary.py")
if "_unicodedata_tek" in d:
    print("ATLANDI: dictionary.py zaten yamali")
else:
    eski = ("                _a = turkish_lower(_row[0].strip())\n"
            "                if _a not in DICTIONARY:\n"
            "                    HAYRAT_TEK[_a] = ")
    yeni = ("                _a = turkish_lower(_row[0].strip())\n"
            "                # Tur M: metin uzun \u00fcnl\u00fc i\u015faretini (\u0101 \u012b \u016b) \u015fapkaya \u00e7evirir (k\u0101dir -> k\u00e2dir): anahtar da \u00e7evrilir\n"
            "                _a = _unicodedata_tek.normalize(\"NFC\", _a).translate(str.maketrans({\"\\u0101\": \"\\u00e2\", \"\\u012b\": \"\\u00ee\", \"\\u016b\": \"\\u00fb\"}))\n"
            "                if _a not in DICTIONARY:\n"
            "                    HAYRAT_TEK[_a] = ")
    if d.count(eski) != 1 or d.count("HAYRAT_TEK = {}\n") != 1:
        print("HATA: dictionary.py'de beklenen HAYRAT_TEK yukleme metni yok")
        sys.exit(1)
    d = d.replace(eski, yeni).replace("HAYRAT_TEK = {}\n", "import unicodedata as _unicodedata_tek\nHAYRAT_TEK = {}\n")
    yaz("app/engine/dictionary.py", d)
    print("TAMAM: dictionary.py (makronlu anahtarlar)")

